func TestUnifiedDiffLargeChangedRegion(t *testing.T) {
	t.Parallel()

	before := strings.Repeat("before\n", 20_000)
	after := strings.Repeat("after\n", 20_000)
	diff := UnifiedDiff("file", before, after)
	if !strings.Contains(diff, "@@ -1,20000 +1,20000 @@\n") ||
		strings.Count(diff, "-before\n") != 20_000 ||
		strings.Count(diff, "+after\n") != 20_000 {
		t.Fatal("large diff does not describe the complete replacement")
	}
}
